/**
 * Maryland hunt / harvest closure polygons.
 *
 * A typed union of three DNR-published closure overlays:
 *   1. `public_harvest_closure` — active public harvest-notice closures from
 *      ClosuresPublicHarvestNotices11_25. Typically shellfish water closures
 *      but also relevant upland harvest restrictions; DNR issues these as
 *      regulatory notices with start + optional end dates and a PDF URL.
 *   2. `oyster_sanctuary` — Manokin River 2010 oyster sanctuary (IBR
 *      08.02.04.15). Listed here (not in fishing regs) because it intersects
 *      areas used for offshore blind hunting — it's a dual-purpose closure.
 *   3. `new_hunting_area` — DNR "New Hunting Area" seasonal polygons pushed
 *      out to the iMap viewer.
 *
 * Source: services.arcgis.com/njFNhDsUCentVYJW/.../
 *   ClosuresPublicHarvestNotices11_25 + ManokinSanctuaryBoundary +
 *   New_Hunting_Area. Pulled 2026-04-19.
 * Simplified DP@20-30m with a 4-pt ring fallback.
 */

export type HuntClosureKind = 'public_harvest_closure' | 'oyster_sanctuary' | 'new_hunting_area';

export interface HuntClosure {
  id: string;
  kind: HuntClosureKind;
  name: string;
  url?: string;
  /** ISO-8601 start date (YYYY-MM-DD) if DNR publishes one. */
  startDate?: string;
  /** ISO-8601 end date. When null, closure is open-ended. */
  endDate?: string;
  notes?: string;
  rings: [number, number][][];
}

